/// <summary>
/// Extension of <c>InventMov_TransferTo</c>
/// </summary>
[ExtensionOf(classstr(InventMov_TransferTo))]
public final class METInventMov_TransferTo_Extension
{
}

Method.Source:
    /// <summary>
    /// This method will return the DefaultDimension based up on the warehouse or InventTransId
    /// </summary>
    /// <returns>
    /// Default dimension
    /// </returns>
    public DimensionDefault defaultDimension()
    {
        DimensionDefault        metDefaultDimension;
        DimensionDefault        metDimWarehouse;

        metDefaultDimension =   next defaultDimension();

       
        InventTable inventTable = InventTable::find(inventTransferLine.itemId);
        if (inventTable.inventModelGroupItem().ModelGroupId == METConstants::StandardCost)
        {
            InventSiteId siteFrom = InventLocation::find(inventTransferTable.InventLocationIdTo).InventSiteId;

            metDimWarehouse = InventSite::changeDimension(inventTable.DefaultDimension, siteFrom);

            if (inventTransferTable.InventLocationIdTo)
            {
                metDimWarehouse = InventLocation::changeDimension(metDefaultDimension, inventTransferTable.InventLocationIdTo);
            }
            DimensionDisplayValue dimensionValue = METHelper::getDimensionValue(metDimWarehouse, METConstants::profitCentre);
            if (dimensionValue)
            {
                metDefaultDimension = metDimWarehouse;
            }
        }

        return metDefaultDimension;
    }
